<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';
$user=require_login($pdo); $pageTitle='Mein Dashboard';
$pageRaw=$_GET['page'] ?? '1'; $page=is_string($pageRaw)&&ctype_digit($pageRaw)?max(1,min(10000,(int)$pageRaw)):1;
$q=$pdo->prepare('SELECT COUNT(*) FROM market_listings WHERE seller_id=?'); $q->execute([$user['id']]); $total=(int)$q->fetchColumn();
$q=$pdo->prepare('SELECT status,COUNT(*) AS count FROM market_listings WHERE seller_id=? GROUP BY status'); $q->execute([$user['id']]); $stats=array_column($q->fetchAll(),'count','status');
$q=$pdo->prepare('SELECT l.*,c.name AS category_name,EXISTS(SELECT 1 FROM market_proxy_bids p WHERE p.listing_id=l.id) AS has_bids FROM market_listings l JOIN market_categories c ON c.id=l.category_id WHERE l.seller_id=? ORDER BY l.created_at DESC,l.id DESC LIMIT 20 OFFSET '.(($page-1)*20)); $q->execute([$user['id']]); $listings=$q->fetchAll();
$labels=['draft'=>'Entwurf','active'=>'Aktiv','paused'=>'Pausiert','ended'=>'Beendet','sold'=>'Verkauft','archived'=>'Archiviert','review'=>'Manuelle Prüfung'];
include __DIR__.'/../includes/header.php';
?>
<main class="page dashboard-page"><div class="page-heading"><p class="eyebrow">Dein Überblick</p><h1>Hallo, <?= h($user['username']) ?>.</h1><p class="muted">Alles, was du anbietest, an einem Ort.</p><div class="button-row"><a class="button" href="/user/create-listing.php">Inserat erstellen</a><a class="button button-ghost" href="/user/profile.php">Profil &amp; Sicherheit</a></div></div>
<?php if (isset($_GET['saved'])): ?><p class="notice" role="status">Dein Angebot wurde gespeichert.</p><?php endif; ?>
<div class="stat-grid"><div class="stat-card"><span>Alle Angebote</span><strong><?= $total ?></strong></div><div class="stat-card"><span>Aktiv</span><strong><?= (int)($stats['active'] ?? 0) ?></strong></div><div class="stat-card"><span>Entwürfe</span><strong><?= (int)($stats['draft'] ?? 0) ?></strong></div><div class="stat-card"><span>Verkauft / beendet</span><strong><?= (int)($stats['sold'] ?? 0)+(int)($stats['ended'] ?? 0) ?></strong></div></div>
<section class="panel"><nav class="button-row" aria-label="Kontobereiche"><a class="button secondary" href="/user/messages.php">Nachrichten</a><a class="button secondary" href="/user/watchlist.php">Merkliste</a><a class="button secondary" href="/user/payments.php">Zahlungen</a></nav><h2>Deine Angebote</h2><p><a class="button secondary" href="/user/billing.php">Bumps &amp; Zahlungsaufträge</a></p><?php if (!$listings): ?><p>Noch ist Platz für deinen ersten Fund.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Angebot</th><th>Status</th><th>Preis</th><th>Aktionen</th></tr></thead><tbody><?php foreach ($listings as $listing): $editable=in_array($listing['status'],['draft','active','paused'],true)&&!$listing['has_bids']&&!($listing['type']==='auction'&&$listing['status']==='active'&&market_expired($listing)); ?><tr><td><strong><?= h($listing['title']) ?></strong><br><small><?= h($listing['category_name']) ?></small></td><td><span class="status"><?= h($labels[$listing['status']] ?? $listing['status']) ?></span></td><td><?= h(money_eur((int)($listing['current_bid_cents'] ?? $listing['price_cents']))) ?></td><td><div class="button-row"><?php if (in_array($listing['status'],['active','ended','sold'],true) && catalog_category_allowed($pdo,(int)$listing['category_id'])): ?><a class="button button-ghost button-small" href="/marketplace/<?= $listing['type']==='auction'?'view-auction.php':'view-item.php' ?>?id=<?= (int)$listing['id'] ?>">Ansehen</a><?php endif; ?><?php if ($editable): ?><a class="button button-ghost button-small" href="/user/edit-listing.php?id=<?= (int)$listing['id'] ?>">Bearbeiten</a><form method="post" action="/actions/manage-auction.php"><?= csrf_field() ?><input type="hidden" name="listing_id" value="<?= (int)$listing['id'] ?>"><select name="action" aria-label="Angebotsaktion"><?php if ($listing['status']==='active'): ?><option value="pause">Pausieren</option><?php endif; ?><?php if ($listing['type']==='fixed' && $listing['status']!=='active'): ?><option value="publish">Veröffentlichen</option><?php endif; ?><?php if ($listing['type']==='fixed'): ?><option value="sold">Als verkauft markieren</option><?php endif; ?><option value="archive">Archivieren</option></select><button class="button button-ghost button-small" type="submit">Ausführen</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php if ($total>20): ?><nav class="pagination" aria-label="Seiten"><?php if ($page>1): ?><a href="?page=<?= $page-1 ?>">Zurück</a><?php endif; ?><span>Seite <?= $page ?></span><?php if ($page*20<$total): ?><a href="?page=<?= $page+1 ?>">Weiter</a><?php endif; ?></nav><?php endif; ?>
</main>
<?php include __DIR__.'/../includes/footer.php'; ?>
